-- Patrimonio sobrio (27-11-2026): tres secciones plegables (bloque nuevo
-- «Sección plegable»), con filetes y una flecha fina, y una abierta cada vez.
-- El trono: foto, texto y su ficha. Enseres: el texto y cuatro piezas con
-- foto grande y su pie (tarjetas en estilo «piezas»). El cortejo: el texto de
-- siempre y el orden de salida, el hábito y el horario en tablas. Las anclas
-- #trono, #enseres y #cortejo pasan a los pliegues y abren su parte.
--
-- Solo si la página sigue con sus bloques de partida (abre con la foto fija
-- del trono): si alguien la ha rehecho en el CMS, no se toca.

UPDATE `ContenidoPagina` SET `datos` = JSON_SET(`datos`, '$.bloques', JSON_EXTRACT('[{"tipo":"texto","titulo":"","presentacion":{"estilo":"margen"},"html":"<h3>Lo que sale a la calle</h3><p>El patrimonio del Grupo Parroquial es fruto del trabajo y la generosidad de sus hermanos. Aquí se recoge en tres partes: el trono de la Virgen, los enseres que la acompañan y el orden del cortejo.</p>"},{"tipo":"pliegue","titulo":"El trono","resumen":"La pieza mayor del Grupo.","presentacion":{"ancla":"trono"}},{"tipo":"fotoTexto","titulo":"","presentacion":{"proporcion":"3:4","alineacionVertical":"arriba"},"url":"/images/trono-candeleria.webp","alt":"El trono de la Virgen, entre la candelería","pie":"El trono de la Virgen, entre la candelería.","html":"<p>Diseñado para realzar la belleza de la Sagrada Titular, el trono combina la solidez de la ebanistería con el brillo de los metales, los bordados y las flores que lo visten en su salida procesional.</p><p>Sus líneas siguen la tradición malagueña y se enriquecen con apliques dorados, lámparas de cristal y un exorno floral que cambia cada año. Lo llevan sus mujeres y hombres de trono, cuyo paso pausado y solemne marca el ritmo de la procesión por las calles del barrio.</p>","boton":"","enlace":""},{"tipo":"datos","titulo":"Ficha","presentacion":{"ancho":"estrecho"},"lineas":[{"etiqueta":"Procedencia","valor":"Antiguo trono del Cristo de la Redención, de la Archicofradía de los Dolores"},{"etiqueta":"Materiales","valor":"Caoba y metal plateado, con jarras y candelería"},{"etiqueta":"Exorno floral","valor":"Floristería de Antequera, distinto cada año"},{"etiqueta":"Portadores","valor":"120 mujeres y hombres de trono (2026)"}]},{"tipo":"pliegue","titulo":"Enseres","resumen":"Insignias, bordado y candelería.","presentacion":{"ancla":"enseres"}},{"tipo":"texto","titulo":"","presentacion":{"ancho":"estrecho"},"html":"<p>Los enseres procesionales acompañan al Grupo Parroquial en la calle. No son meros adornos, sino signos visibles de una identidad que se transmite de generación en generación, y su cuidado es tarea de todos los hermanos.</p>"},{"tipo":"tarjetas","titulo":"","presentacion":{"estilo":"piezas","columnas":"2"},"tarjetas":[{"titulo":"Cruz de guía","descripcion":"Abre el cortejo y marca el camino. Madera con cantoneras y escudo de metal plateado.","enlace":"","etiqueta":"Insignias","foto":"/images/enseres/cruz-de-guia.webp","fotoAlt":"La cruz de guía del Grupo, entre los nazarenos y los banderines"},{"titulo":"Banderines","descripcion":"Acompañan a la cruz de guía en el primer tramo. Relieve en metal plateado sobre terciopelo negro, con su número en la punta.","enlace":"","etiqueta":"Insignias","foto":"/images/enseres/banderines.webp","fotoAlt":"Los banderines del cortejo, de noche, con sus relieves de metal plateado"},{"titulo":"Manto de salida","descripcion":"Terciopelo azul noche bordado en oro y plata, con el anagrama repetido por toda la cola. Restaurado en 2018.","enlace":"","etiqueta":"Bordado","foto":"/images/enseres/manto-de-salida.webp","fotoAlt":"Detalle del manto azul de la Virgen, bordado en oro y plata"},{"titulo":"Candelería","descripcion":"La cera del trono lleva el escudo del Grupo. Se enciende al anochecer y alumbra la cara de la Virgen.","enlace":"","etiqueta":"Trono","foto":"/images/enseres/candeleria.webp","fotoAlt":"Cirios del trono con el escudo del Grupo, delante de la Virgen"}]},{"tipo":"pliegue","titulo":"El cortejo","resumen":"Su orden, el hábito y el horario.","presentacion":{"ancla":"cortejo"}},{"tipo":"texto","titulo":"","presentacion":{"ancho":"estrecho"},"html":"<p>Abre el cortejo la cruz de guía, escoltada por dos faroles, y tras ella los banderines del primer tramo. Detrás van los nazarenos con su cirio, en tramos, cada uno con su insignia y su mayordomo, que cuida el orden y el paso.</p><p>Antes del trono, la presidencia: la junta de gobierno con sus varas y el estandarte del Grupo Parroquial. Luego la Virgen, sobre los hombros de sus mujeres y hombres de trono, y cerrando la marcha la banda que la acompaña.</p><p>Los hermanos que quieran salir se apuntan en el reparto de puestos, que se abre unas semanas antes del Sábado de Pasión. <a href=\\"/sabado-de-pasion/recorrido\\">Ver el recorrido</a>.</p>"},{"tipo":"datos","titulo":"Orden de salida · 2026","presentacion":{"ancho":"estrecho"},"lineas":[{"etiqueta":"Cruz de guía y faroles","valor":""},{"etiqueta":"Penitentes infantiles","valor":"35"},{"etiqueta":"Nazarenos con cirio","valor":"100"},{"etiqueta":"Insignias y estandarte","valor":""},{"etiqueta":"Presidencia","valor":""},{"etiqueta":"Trono de la Virgen","valor":"120 portadores"},{"etiqueta":"Banda","valor":"Banda de Música Santa Cecilia"}]},{"tipo":"datos","titulo":"Hábito","presentacion":{"ancho":"estrecho"},"lineas":[{"etiqueta":"Túnica y capirote","valor":"Sarga negra; escudo pasionista en blanco en el capirote"},{"etiqueta":"Cíngulo","valor":"Burdeos"},{"etiqueta":"Cirio","valor":"Marfil"}]},{"tipo":"datos","titulo":"Horario","presentacion":{"ancho":"estrecho"},"lineas":[{"etiqueta":"Salida","valor":"18:00, Santa María Goretti"},{"etiqueta":"Encierro","valor":"23:30"}]}]', '$'))
WHERE `slug` = 'patrimonio'
  AND JSON_VALUE(`datos`, '$.bloques[0].tipo') = 'fotoFija'
  AND JSON_VALUE(`datos`, '$.bloques[0].presentacion.ancla') = 'trono';
